internal object DuaAsDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("নতুন চন্দ্ৰ দেখা", "হে আল্লাহ, এই চন্দ্ৰখন আশীৰ্বাদ, বিশ্বাস, নিৰাপত্তা আৰু ইছলামৰ সৈতে আমাৰ ওপৰত উদয় হওক। (হে চন্দ্ৰ,) মোৰ প্ৰভু আৰু তোমাৰ প্ৰভু আল্লাহ।", "নতুন চন্দ্ৰ দেখাৰ পিছত।", "প্ৰত্যেক নতুন মাহৰ বাবে সুন্নাহ দুআ।"),
        "dua_janaza_adult" to DuaText("জনাজা প্ৰাৰ্থনা (প্ৰাপ্তবয়স্ক)", "হে আল্লাহ, আমাৰ জীৱিত আৰু মৃত, উপস্থিত আৰু অনুপস্থিতসকল, আমাৰ যুৱক-যুৱতী আৰু বৃদ্ধ, আমাৰ পুৰুষ-মহিলা আৰু পুৰুষসকল ক্ষমা কৰা। হে আল্লাহ, আমাৰ ভিতৰত যিজনক তুমি জীয়াই ৰাখ, তাক ইছলামত জীয়াই ৰাখ, আৰু আমাৰ ভিতৰত যিজনক তুমি মৰাই দিয়া, তাক বিশ্বাসৰ ভিত্তিত মৰাই দিয়া।", "অন্ত্যেষ্টিক্ৰিয়াৰ প্ৰাৰ্থনাৰ তৃতীয় তাকবীৰৰ পিছত।", "এজন মৃত প্ৰাপ্তবয়স্কৰ বাবে সুন্নাহ দুআ।"),
        "dua_janaza_child" to DuaText("জনাজা প্ৰাৰ্থনা (শিশু)", "হে আল্লাহ, তেওঁক আমাৰ বাবে এজন আগতীয়া (আৰু আয়োজক) কৰি তোলক, তেওঁক আমাৰ বাবে এক পুৰস্কাৰ আৰু এক ধন কৰা, আৰু তেওঁক আমাৰ বাবে এজন মধ্যস্থতাকাৰী কৰা যাৰ মধ্যস্থতা গ্ৰহণ কৰা হয়।", "এটা শিশুৰ অন্ত্যেষ্টিক্ৰিয়াৰ প্ৰাৰ্থনাত (এটা ছোৱালীৰ বাবে'ইজ'আল্হা'বুলি কোৱা হয়)।", "হানাফিসকলে অনুশীলন কৰা সুন্নাহ দুআ।"),
        "dua_mayyit_awf" to DuaText("মৃতসকলৰ বাবে বিশদ দুৱা", "হে আল্লাহ, তেওঁক ক্ষমা কৰা, তেওঁৰ ওপৰত দয়া কৰা, তেওঁক সুস্থ কৰি তোলা আৰু তেওঁক ক্ষমা কৰা। তেওঁৰ অভ্যর্থনা সন্মানজনক আৰু তেওঁৰ কবৰটো বহল কৰা, তেওঁক পানী, বৰফ আৰু শিলাবৃষ্টিৰে ধুই পেলোৱা, আৰু বগা কাপোৰেৰে ময়লা পৰিষ্কাৰ কৰাৰ দৰে তেওঁক পাপৰ পৰা পৰিষ্কাৰ কৰা।", "অন্ত্যেষ্টিক্ৰিয়াৰ প্ৰাৰ্থনা বা মৃত ব্যক্তিৰ বাবে।", "আউফ ইবন মালিক (আৰ. এ.)-এ ইচ্ছা কৰিছিল যে তেওঁ সেই মৃত ব্যক্তি আছিল।"),
        "dua_visiting_graves" to DuaText("সমাধিক্ষেত্ৰসমূহ ভ্ৰমণ কৰা", "হে এই ঘৰৰ মুমিন আৰু মুছলমান লোকসকল, আপোনালোকৰ ওপৰত শান্তি থাকক। আমিও, যদি আল্লাহ ইচ্ছা কৰে, আপোনালোকৰ সৈতে যোগ দিম। মই আল্লাহৰ ওচৰত আমাৰ আৰু আপোনালোকৰ কল্যাণৰ বাবে অনুৰোধ জনাইছো।", "কবৰস্থানত প্ৰৱেশ কৰোঁতে।", "কবৰসমূহ ভ্ৰমণ কৰিলে মৃত্যু আৰু পৰৱৰ্তী সময়ৰ কথা মনত পৰে।"),
        "dua_closing_eyes" to DuaText("মৃত ব্যক্তিৰ চকু বন্ধ কৰাৰ পিছত", "হে আল্লাহ, ক্ষমা কৰা, পথপ্ৰদৰ্শকৰ মাজত তেওঁৰ পদ বৃদ্ধি কৰা, তেওঁ যিজনক এৰি গৈছে তেওঁলোকৰ ভিতৰত তেওঁৰ উত্তৰাধিকাৰী হোৱা। হে বিশ্বজগতৰ প্ৰভু, আমাক আৰু তেওঁক ক্ষমা কৰা, তেওঁৰ সমাধিখন বহল কৰা আৰু ইয়াক পোহৰেৰে ভৰাই দিয়া।", "মৃত ব্যক্তিগৰাকীৰ চকু বন্ধ কৰাৰ সময়ত (তেওঁৰ নাম উল্লেখ কৰি)।", "নবী ছলীহ আলীহ ৱাছলে আবু ছালামাহ (আৰ. এ.) ৰ বাবে এই দুআ কৰিছিল।"),
        "dua_condolence" to DuaText("সমবেদনা (তাজিয়া)", "নিশ্চিতভাৱে তেওঁ যি লৈ গৈছিল সেয়া আল্লাহৰ আৰু তেওঁ যি দিছিল সেয়া তেওঁৰ, আৰু তেওঁৰ ওচৰত থকা সকলো বস্তুৰে এটা নিৰ্দিষ্ট সময়সীমা আছে, সেয়েহে ধৈৰ্য্যশীল হওক আৰু পুৰস্কাৰৰ আশা ৰাখক।", "মৃত্যুৰ পিছত এটা পৰিয়াললৈ সমবেদনা জ্ঞাপন কৰা।", "নবী (ছাঃ)-এ তেওঁৰ কন্যালৈ এই বাৰ্তা প্ৰেৰণ কৰিছিল।"),
        "dua_placing_in_grave" to DuaText("মৃতজনক কবৰত ৰখা", "আল্লাহৰ নামত আৰু আল্লাহৰ ৰাছুল (ছাঃ)-ৰ পথত।", "যেতিয়া মৃতজনক কবৰলৈ নামাই দিয়া হয়।", "সমাধিস্থ কৰাৰ সুন্নাহ দুআ।"),
        "dua_sneezing" to DuaText("হাঁচি।", "সকলো প্ৰশংসা আল্লাহৰ বাবে।-আল্লাহ আপোনাৰ ওপৰত দয়া কৰক।-আল্লাহ আপোনাক পথ দেখুৱাওক আৰু আপোনাৰ কাম-কাজ সঠিক কৰক।", "হাঁচি দিয়াৰ সময়ত শ্ৰোতাজনে'ইৰহামুকাল্লাহ \"বুলি কয়, তাৰ পিছত হাঁচি দিয়া লোকে উত্তৰ দিয়ে।", "এইটো আন এজন মুছলমানৰ ওপৰত এজন মুছলমানৰ এক অধিকাৰ।"),
        "dua_toilet_enter" to DuaText("শৌচাগাৰত প্ৰৱেশ কৰা হৈছে", "আল্লাহৰ নামত। হে আল্লাহ, মই অপবিত্র জিন পুৰুষ আৰু মহিলাৰ পৰা তোমাৰ আশ্ৰয় বিচাৰো।", "শৌচাগাৰলৈ যোৱাৰ আগতে বাওঁ ভৰিৰে যাওক।", "বিসমিল্লাহ জিন আৰু ব্যক্তিৰ মাজত এটা পৰ্দা হৈ পৰে।"),
        "dua_toilet_exit" to DuaText("শৌচাগাৰ এৰি যোৱা", "(হে আল্লাহ,) মই তোমাৰ পৰা ক্ষমা বিচাৰো।", "শৌচাগাৰৰ পৰা ওলাই অহাৰ সময়ত সোঁ ভৰিৰে ওলাই যাওক।", "প্ৰবক্তা ছলীহ আলীহ ৱাছলে শৌচাগাৰৰ পৰা ওলাই অহাৰ সময়ত এই কথা কৈছিল।"),
        "dua_thanking" to DuaText("কাৰোবাক ধন্যবাদ জনাওঁ", "আল্লাহ তা'আলা আপোনাক ভালৰ পুৰস্কাৰ দিয়ক।", "যেতিয়া কোনোবাই আপোনাৰ ওপৰত কোনো অনুৰাগ কৰে।", "যিজনে এই কথা কৈছে তেওঁ সম্পূৰ্ণৰূপে কৃতজ্ঞতা প্ৰকাশ কৰিছে।"),
        "dua_love_for_allah" to DuaText("যেতিয়া কোনোবাই কয়'মই তোমাক আল্লাহৰ বাবে ভাল পাওঁ'", "তেওঁ (আল্লাহ), যাৰ বাবে আপুনি মোক ভাল পায়, আপোনাক ভাল পায়।", "যেতিয়া কোনোবাই কয়'মই তোমাক আল্লাহৰ বাবে ভাল পাওঁ'।", "সুন্নাই আল্লাহৰ প্ৰতি থকা প্ৰেমৰ উত্তৰ দিয়ে।"),
        "dua_seeing_muslim_smile" to DuaText("শুভেচ্ছা (ছালাম)", "আপোনাৰ ওপৰত শান্তি থাকক, আৰু আল্লাহৰ দয়া আৰু তেওঁৰ আশীৰ্বাদ থাকক।", "যেতিয়া এজন মুছলমানক লগ পায়।", "সম্পূৰ্ণ ছালাম ক'লে ত্ৰিশটা ভাল কাম কৰে।"),
        "dua_dressing" to DuaText("কাপোৰ পিন্ধা", "সকলো প্ৰশংসা সেই আল্লাহৰ বাবে যিয়ে মোক এই পোছাক পিন্ধাইছিল আৰু মোৰ ফালৰ পৰা কোনো শক্তি বা ক্ষমতা অবিহনে মোক ইয়াক প্ৰদান কৰিছিল।", "যেতিয়া কাপোৰ পিন্ধিব লাগে।", "অতীতৰ পাপসমূহৰ ক্ষমাৰ সুখৰ খবৰ।"),
        "dua_rooster_donkey" to DuaText("কুকুৰা বা গাধৰ শব্দ শুনা", "হে আল্লাহ, মই তোমাৰ অনুগ্ৰহ (কুকুৰ) বিচাৰো।-মই শাপিত (গাধা) শ্বেতানৰ পৰা আল্লাহৰ আশ্ৰয় বিচাৰো।", "কুকুৰা এটাৰ কথা শুনি আল্লাহৰ অনুৰাগ বিচাৰে; গাধৰ ব্ৰেৰ কথা শুনি শায়তানৰ পৰা আশ্ৰয় লয়।", "কুকুৰটোৱে এজন দূতক দেখে আৰু গাধটোৱে এটা শয়তান দেখে।"),
        "dua_something_liked" to DuaText("প্ৰশংসনীয় কিবা দেখা (দুষ্ট চকুৰ বিৰুদ্ধে)", "আল্লাহে যি ইচ্ছা কৰিছে। হে আল্লাহ্, ইয়াক আশীৰ্বাদ দিয়ক।", "কাৰোবাৰ প্ৰশংসনীয় কিবা এটা দেখি আশীৰ্বাদৰ বাবে প্ৰাৰ্থনা কৰক।", "আশীৰ্বাদৰ বাবে প্ৰাৰ্থনা কৰিলে দুৰ্বল চকুৰ পৰা ৰক্ষা পোৱা যায়।"),
        "dua_sell_buy_debt_repaid" to DuaText("ঋণ পৰিশোধ কৰোঁতে", "ঈশ্বৰে আপোনাক আপোনাৰ পৰিয়াল আৰু আপোনাৰ সম্পদৰ ওপৰত আশীৰ্বাদ দিয়ক।", "ঋণ পৰিশোধ কৰাৰ সময়ত ঋণদাতাৰ বাবে।", "ঋণৰ বাবে ধন ঘূৰাই দিয়া হৈছে ধন্যবাদ আৰু পৰিশোধ।"),
        "dua_talbiyah" to DuaText("তালবিয়া", "এইয়া মই, হে আল্লাহ, এইয়া মই। এইয়া মই, তোমাৰ কোনো অংশীদাৰ নাই, এইয়া মই। সকলো প্ৰশংসা, আশীৰ্বাদ আৰু আধিপত্য নিশ্চয় তোমাৰ। তোমাৰ কোনো অংশীদাৰ নাই।", "ইহৰামত প্ৰৱেশ কৰাৰ পিছত জোৰেৰে।", "হজ্জ আৰু উমৰাহৰ প্ৰতীক।"),
        "dua_yamani_hajar" to DuaText("ৰুকন যামানী আৰু হাজৰ আসৱাদৰ মাজত", "হে আমাৰ প্ৰভু, আমাক এই পৃথিৱীত ভাল আৰু পৰৱৰ্তী সময়ত ভাল দিয়ক, আৰু আমাক জুইৰ শাস্তিৰ পৰা ৰক্ষা কৰক।", "তাৱাফত, য়েমেনি কৰ্ণাৰ আৰু ব্লেক ষ্টোনৰ মাজত।", "নবী (ছাঃ)-এ তাৱাফৰ এই স্থানত এই পাঠ কৰিছিল।"),
        "dua_safa_marwa" to DuaText("চাফা আৰু মাৰৱাহৰ ওপৰত", "কেৱল আল্লাহৰ বাহিৰে, কেৱল তেওঁৰেই উপাসনা কৰাৰ অধিকাৰ নাই। তেওঁৰ শাসন আৰু তেওঁৰেই প্রশংসা, আৰু তেওঁৰ সকলো বস্তুৰ ওপৰত ক্ষমতা আছে। কেৱল আল্লাহৰ বাহিৰে কাৰো উপাসনা কৰাৰ অধিকাৰ নাই। তেওঁ নিজৰ প্ৰতিশ্ৰুতি পূৰণ কৰিছিল, তেওঁৰ বান্দক সহায় কৰিছিল আৰু কেৱল সংঘক পৰাস্ত কৰিছিল।", "ছাফা আৰোহণ কৰা আৰু কিবলাৰ ফালে মুখ কৰা (তিনিবাৰ)।", "চাফা আৰু মাৰৱাহৰ ওপৰত নবী ছাল্লীহ আলীহ ৱাছলামৰ ধিক্ৰ।"),
        "dua_arafah" to DuaText("আৰাফাহৰ দিনৰ শ্ৰেষ্ঠ দুৱা", "আল্লাহৰ বাহিৰে উপাসনাৰ যোগ্য আন কোনো নাই; তেওঁ একক, তেওঁৰ কোনো অংশীদাৰ নাই। তেওঁৰে শাসন আৰু তেওঁৰেই প্ৰশংসা, আৰু তেওঁ সকলো বস্তুৰ ওপৰত ক্ষমতাশালী।", "আৰাফাহৰ দিন-শ্ৰেষ্ঠ দুআ।", "আৰাফাহৰ দিনৰ দুআ হৈছে সৰ্বশ্ৰেষ্ঠ দুআ, আৰু এই শব্দবোৰ হৈছে সৰ্বশ্ৰেষ্ঠ শব্দ।"),
        "dua_takbeer_tashreeq" to DuaText("তাকবীৰ-ই-তাশ্ৰীক", "আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ। আল্লাহৰ বাহিৰে কোনো ইলাহ নাই। আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আল্লাহ হৈছে সৰ্বশ্ৰেষ্ঠ, আৰু সকলো প্ৰশংসা আল্লাহৰ বাবে।", "9 ধুল-হিজ্জাৰ ফজৰৰৰ পৰা 13 ধুল-হিজ্জাৰ আছৰলৈকে প্ৰতিটো বাধ্যতামূলক প্ৰাৰ্থনাৰ পিছত।", "হানাফিসকলৰ মতে আলী আৰু ইবন মাছুদ (আৰ. এ.)-ৱাজিবৰ পৰা প্ৰতিবেদন দিয়া হৈছে।"),
        "dua_zamzam" to DuaText("জামজাম পান কৰা", "হে আল্লাহ, মই আপোনাক উপকাৰী জ্ঞান, প্ৰচুৰ যোগান আৰু প্ৰতিটো ৰোগৰ পৰা নিৰাময়ৰ বাবে অনুৰোধ জনাইছো।", "জামজাম খোৱাৰ সময়ত, আপুনি যি ইচ্ছা কৰক তাৰ বাবে দুৱা বনাওক।", "জামজাম যিখিনিৰ বাবে সুৰাপান কৰা হয় তাৰ বাবে হয় (ইবন মাজাহ 3062)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("সৃষ্টিৰ ওপৰত চিন্তা কৰা হৈছে", "হে আমাৰ প্ৰভু, তুমি এই সকলোবোৰ নিরর্থকভাৱে সৃষ্টি কৰা নাই। তুমি গৌৰৱান্বিত, গতিকে আমাক অগ্নিৰ শাস্তিৰ পৰা সুৰক্ষা দিয়া।", "যিসকলে আকাশ আৰু পৃথিৱীৰ সৃষ্টিৰ ওপৰত চিন্তা কৰে তেওঁলোকৰ দুআ।", "বুজা মানুহৰ দুআ (উলুল-আলবাব)।"),
        "dua_q_sami_na_munadiyan" to DuaText("আমি বিশ্বাসৰ বাবে আহ্বান কৰা লোকজনক শুনিছিলোঁ", "হে আমাৰ প্ৰভু, আমি এজন লোকৰ পৰা বিশ্বাসী হোৱাৰ আহ্বান শুনিছো, তেওঁ কয়,'তোমাৰ প্ৰভুৰ ওপৰত বিশ্বাস ৰাখ \", আৰু আমি বিশ্বাস কৰিলো। হে আমাৰ প্ৰভু, আমাৰ পাপবোৰ ক্ষমা কৰা, আমাৰ অপৰাধবোৰ আমাৰ পৰা আঁতৰাই দিয়া আৰু সৎকাৰীসকলৰ সৈতে আমাক মৰাই দিয়া।", "ধৰ্মনিষ্ঠসকলৰ মাজত বিশ্বাস আৰু মৃত্যুৰ বাবে এটা দুআ।", "ক্ষমা আৰু এক ভাল সমাপ্তিৰ বাবে এটা দুআ।"),
        "dua_q_atina_ma_waadtana" to DuaText("আপুনি যি প্ৰতিশ্ৰুতি দিছিল আমাক দিয়ক", "হে আমাৰ প্ৰভু, তুমি তোমাৰ ৰাছুলসকলৰ জৰিয়তে আমাক যি প্ৰতিশ্ৰুতি দিছা, তাক আমাক দিয়া, আৰু কিয়ামতৰ দিনা আমাক অপমানিত নকৰিবা। নিশ্চয় তুমি তোমাৰ প্ৰতিশ্ৰুতি ভংগ নকৰা।", "পুনৰুত্থানৰ দিনা অপমানৰ পৰা শৰণাধিকাৰী।", "পৰৱৰ্তী সময়ত সন্মান বিচাৰি থকা।"),
        "dua_q_israfana" to DuaText("আমাৰ অতিৰিক্ততা ক্ষমা কৰক", "হে আমাৰ প্ৰভু, আমাৰ পাপ আৰু আমাৰ কাম-কাজত আমাৰ অতিৰিক্ততা আমাক ক্ষমা কৰা, আমাৰ ভৰি দৃঢ় কৰা আৰু অবিশ্বাসী লোকসকলৰ বিৰুদ্ধে আমাক সহায় কৰা।", "পূৰ্বৰ নবীসকলৰ সঙ্গীসকলৰ দুআ।", "দৃঢ়তা আৰু ক্ষমাৰ বাবে এটা দুআ।"),
        "dua_q_jamiun_nas" to DuaText("আপুনি মানৱজাতিক একত্ৰিত কৰিব।", "হে আমাৰ প্ৰভু, তুমি নিশ্চিতভাৱে মানুহৰ এনে এটা দিনত একত্ৰিত কৰিবা য'ত কোনো সন্দেহ নাই। নিশ্চয়ই আল্লাহে নিজৰ প্ৰতিশ্ৰুতি ভংগ নকৰে।", "পুনৰুত্থানৰ দিনা নিশ্চিততা নিশ্চিত কৰা।", "জ্ঞানৰ ওপৰত দৃঢ়ভাৱে আধাৰিত লোকসকলৰ দ্বৈত।"),
        "dua_q_maash_shahidin" to DuaText("আমাক সাক্ষীসকলৰ মাজত লিখক", "হে আমাৰ প্ৰভু, আমি বিশ্বাস কৰিছোঁ, গতিকে আমাক সাক্ষীসকলৰ মাজত লিখক।", "যিসকলে সত্যক চিনাক্ত কৰিছিল আৰু বিশ্বাস কৰিছিল তেওঁলোকৰ দুআ।", "নিজৰ বিশ্বাস গ্ৰহণ কৰাৰ বাবে এটা দুআ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("অপৰাধ কৰাসকলৰ সৈতে নহয়", "হে আমাৰ প্ৰভু, আমাক অন্যায়কাৰী লোকসকলৰ লগত ৰাখিবা।", "আল-আৰাফৰ লোকসকলৰ দুআ।", "অন্যায়কাৰীসকলৰ ভাগ্যৰ পৰা আশ্ৰয় লওক।"),
        "dua_q_tawaffana_muslimin" to DuaText("মুছলমান হিচাপে ধৈর্য আৰু মৃত্যু", "হে আমাৰ প্ৰভু, আমাৰ ওপৰত ধৈৰ্য্য প্ৰয়োগ কৰক আৰু আমাক মুছলমান হিচাপে মৰাই দিয়ক।", "ফৰৌণৰ যাদুকৰীসকলৰ দুআ যেতিয়া তেওঁলোকে বিশ্বাস কৰিছিল।", "পৰীক্ষাত ধৈর্য আৰু বিশ্বাসৰ ওপৰত অন্ত পৰে।"),
        "dua_q_la_tajalna_fitnah" to DuaText("নিৰ্যাতনৰ বাবে বিচাৰ নহয়", "আমি আল্লাহৰ ওপৰত নিৰ্ভৰ কৰোঁ। হে আমাৰ প্ৰভু, আমাক অন্যায়কাৰী লোকসকলৰ বাবে পৰীক্ষা নকৰিবা, আৰু আপোনাৰ দয়াই আমাক অবিশ্বাসী লোকসকলৰ পৰা ৰক্ষা কৰক।", "মূছা (আৰ. এছ.) ৰ লোকসকলৰ দুআ।", "নিৰ্যাতন আৰু নিৰ্যাতনৰ পৰা উদ্ধাৰৰ বাবে এটা দুআ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("ক্ষমাৰ বাবে নুহৰ দুআ (আৰু)", "হে মোৰ প্ৰভু, মই তোমাৰ ওচৰত আশ্ৰয় বিচাৰোঁ, তোমাৰ ওচৰত এনে বস্তু বিচাৰি নাপালো যাৰ বিষয়ে মোৰ কোনো জ্ঞান নাই। আৰু যেতিয়ালৈকে তুমি মোক ক্ষমা নকৰা আৰু মোৰ ওপৰত দয়া নকৰা, মই ক্ষতিগ্রস্থসকলৰ ভিতৰত হ'ম।", "নবী নূহ (আৰু আৰ. আৰ.)-ৰ অনুতাপৰ দুআ।", "সঠিক আচৰণৰে সোধাৰ এটা শিক্ষা।"),
        "dua_q_mudkhala_sidq" to DuaText("সত্যৰ প্ৰৱেশ আৰু প্ৰস্থান", "হে মোৰ প্ৰভু, মোক সত্যৰ সৈতে প্ৰৱেশ কৰা আৰু সত্যৰ সৈতে প্ৰস্থান কৰা, আৰু মোক আপোনাৰ পৰা এক সমৰ্থন কৰা কৰ্তৃত্ব প্ৰদান কৰক।", "নতুন কাম এটা কৰাৰ আগতে, ঘৰ বা ঠাই।", "দুৱাই হিজ্ৰাহৰ সময়ত নবী ছাল্লাহ আলীহ ৱাছলামক শিক্ষা দিছিল।"),
        "dua_q_la_tadharni_fardan" to DuaText("জাকাৰিয়াৰ দুৱা (আৰ. এছ.)-মোক অকলে এৰি নিদিবা।", "হে মোৰ প্ৰভু, মোক অকলে এৰি নিদিবা, আৰু তুমি উত্তৰাধিকাৰীসকলৰ ভিতৰত সৰ্বশ্ৰেষ্ঠ।", "সন্তান বিচাৰি থকা সকলৰ বাবে।", "এই দুআৰ জৰিয়তে আল্লাহে ইয়াহিয়া (আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আ"),
        "dua_q_munzalan_mubarakan" to DuaText("এক ধন্য অৱতৰণ স্থান", "হে মোৰ প্ৰভু, মোক এটা আশীৰ্বাদপ্ৰাপ্ত অৱতৰণ স্থানত অৱতৰণ কৰিবলৈ দিয়ক, আৰু আপুনি মাটিত অনা লোকসকলৰ ভিতৰত শ্ৰেষ্ঠ।", "নতুন ঘৰলৈ যোৱাৰ সময়ত বা ক \"ৰবাত ৰৈ যোৱাৰ সময়ত-নুহ (এ. এছ) ৰ দুআ।", "নতুন ঠাইত আশীৰ্বাদৰ বাবে এটা দুআ।"),
        "dua_q_amanna_faghfir" to DuaText("আমি বিশ্বাস কৰোঁ, গতিকে আমাক ক্ষমা কৰক।", "হে আমাৰ প্ৰভু, আমি বিশ্বাস কৰিছোঁ, গতিকে আমাক ক্ষমা কৰক আৰু আমাৰ ওপৰত দয়া কৰক, আৰু আপুনি দয়ালুসকলৰ ভিতৰত সৰ্বশ্ৰেষ্ঠ।", "আল্লাহৰ সৎকৰ্মশীল দাসসকলৰ দুআ।", "ক্ষমা আৰু দয়াৰ বাবে এক ব্যাপক দুআ।"),
        "dua_q_isrif_jahannam" to DuaText("নৰকৰ শাস্তিৰ পৰা আঁতৰি থাকক", "হে আমাৰ প্ৰভু, আমাৰ পৰা জাহান্নামৰ শাস্তি আঁতৰাই ৰাখক, ইয়াৰ শাস্তি সদায়েই চলি থকা। এইটো এক বেয়া বসতি আৰু বাসস্থান।", "পরম দয়ালু ('ইবাদত আৰ-ৰহমান) ৰ দাসসকলৰ দুআ।", "নৰকৰ পৰা আশ্ৰয়ৰ বাবে কোৰাণৰ দুআ।"),
        "dua_q_hab_li_hukman" to DuaText("ইব্ৰাহিমৰ দুৱা (আৰু আৰু)-জ্ঞান আৰু জান্নাহ", "হে মোৰ প্ৰভু, মোক প্রজ্ঞা প্ৰদান কৰক আৰু ধাৰ্মিকসকলৰ সৈতে মোৰ সৈতে যোগ দিয়ক, পৰৱৰ্তী প্ৰজন্মৰ মাজত মোক এক সন্মানীয় উল্লেখ কৰক, আৰু মোক আনন্দৰ বাগিচাৰ উত্তৰাধিকাৰীসকলৰ ভিতৰত কৰি তুলিব।", "প্রজ্ঞা বিচাৰি, ধৰ্মীয় আৰু স্বৰ্গৰ সংগ।", "ইব্ৰাহিম (এ. এছ.) ৰ এক ব্যাপক দুআ।"),
    )
